function CalcBaseFee(config, parentHeader):
  // First EIP-1559 block returns initial base fee
  if not config.IsLondon(parentHeader.Number):
    return params.InitialBaseFee  // 1 gwei

  parentGasTarget = parentHeader.GasLimit / config.ElasticityMultiplier()  // ElasticityMultiplier = 2

  // If parent used exactly target gas, base fee unchanged
  if parentHeader.GasUsed == parentGasTarget:
    return parentHeader.BaseFee

  // Parent used more than target: increase base fee
  if parentHeader.GasUsed > parentGasTarget:
    gasUsedDelta = parentHeader.GasUsed - parentGasTarget
    baseFeeIncrease = max(1, (parentHeader.BaseFee * gasUsedDelta / parentGasTarget) / config.BaseFeeChangeDenominator())
    return parentHeader.BaseFee + baseFeeIncrease

  // Parent used less than target: decrease base fee
  else:
    gasUsedDelta = parentGasTarget - parentHeader.GasUsed
    baseFeeDecrease = (parentHeader.BaseFee * gasUsedDelta / parentGasTarget) / config.BaseFeeChangeDenominator()
    return max(0, parentHeader.BaseFee - baseFeeDecrease)

  // BaseFeeChangeDenominator = 8, so max change = 12.5% per block
