function CalcExcessBlobGas(config, parentHeader, currentTimestamp):
  blobConfig = latestBlobConfig(config, currentTimestamp)  // Fork-specific target/max blobs
  isOsaka = config.IsOsaka(config.LondonBlock, currentTimestamp)

  parentExcessBlobGas = parentHeader.ExcessBlobGas  // 0 if not set
  parentBlobGasUsed = parentHeader.BlobGasUsed      // 0 if not set

  excessBlobGas = parentExcessBlobGas + parentBlobGasUsed
  targetGas = blobConfig.Target * params.BlobTxBlobGasPerBlob  // Target blobs * 131072

  if excessBlobGas < targetGas:
    return 0

  // EIP-7918 (post-Osaka): apply scaled excess if blob price below reserve price
  if isOsaka:
    reservePrice = params.BlobBaseCost * parentHeader.BaseFee  // 8192 * baseFee
    blobPrice = blobConfig.blobPrice(parentExcessBlobGas)
    if reservePrice > blobPrice:
      scaledExcess = parentBlobGasUsed * (blobConfig.Max - blobConfig.Target) / blobConfig.Max
      return parentExcessBlobGas + scaledExcess

  // Original EIP-4844: subtract target from excess
  return excessBlobGas - targetGas
