function blobBaseFee(excessBlobGas):
  minBlobGasPrice = 1 wei
  updateFraction = blobConfig.UpdateFraction  // Fork-specific, typically 3338477
  return fakeExponential(minBlobGasPrice, excessBlobGas, updateFraction)

function fakeExponential(factor, numerator, denominator):
  // Approximates factor * e^(numerator/denominator) using Taylor expansion
  output = 0
  accumulator = factor * denominator
  i = 1
  while accumulator > 0:
    output += accumulator
    accumulator = (accumulator * numerator) / denominator / i
    i += 1
  return output / denominator
