function IntrinsicGas(data, accessList, authList, isContractCreation, isHomestead, isIstanbul, isShanghai):
  gas = TxGas  // 21000 base cost for all transactions

  if isContractCreation and isHomestead:
    gas += TxGasContractCreation  // Additional 32000 for contract creation

  // Calldata cost
  if len(data) > 0:
    numZeroBytes = count zero bytes in data
    numNonZeroBytes = len(data) - numZeroBytes

    gas += numZeroBytes * TxDataZeroGas  // 4 gas per zero byte
    if isIstanbul:
      gas += numNonZeroBytes * TxDataNonZeroGasEIP2028  // 16 gas per non-zero byte after Istanbul
    else:
      gas += numNonZeroBytes * TxDataNonZeroGasFrontier  // 68 gas before Istanbul

    // EIP-3860: init code size cost (Shanghai+)
    if isContractCreation and isShanghai:
      numWords = (len(data) + 31) / 32
      gas += numWords * InitCodeWordGas  // 2 gas per word

  // EIP-2930: access list cost
  gas += len(accessList.addresses) * TxAccessListAddressGas  // 2400 per address
  gas += len(accessList.storageKeys) * TxAccessListStorageKeyGas  // 1900 per storage key

  // EIP-7702: authorization list cost
  gas += len(authList) * TxAuthTupleGas  // 12500 per auth tuple

  return gas
