function FloorDataGas(data):
  if len(data) == 0:
    return 0

  numNonZeroBytes = count non-zero bytes in data
  totalTokens = numNonZeroBytes * TxTokenPerNonZeroByte  // 4 tokens per non-zero byte
  floorGas = totalTokens * TxCostFloorPerToken  // 10 gas per token

  return floorGas
  // Result: 40 gas per non-zero byte minimum (4 * 10), compared to 16 from EIP-2028
