function EffectiveGasTip(tx, baseFee):
  // For legacy transactions (no max fee)
  if tx.Type() == LegacyTx:
    return tx.GasPrice() - baseFee

  // For EIP-1559 transactions
  maxFeePerGas = tx.MaxFeePerGas()
  maxPriorityFeePerGas = tx.MaxPriorityFeePerGas()

  // Effective gas price is min of maxFeePerGas or baseFee + maxPriorityFeePerGas
  effectiveGasPrice = min(maxFeePerGas, baseFee + maxPriorityFeePerGas)

  // Effective tip is what miner receives
  effectiveTip = effectiveGasPrice - baseFee
  return effectiveTip

  // Note: baseFee is burned, effectiveTip goes to coinbase
