function SortTransactionsForBlock(txs, baseFee):
  // Group transactions by sender account
  accountTxs = groupBySender(txs)

  // For each account, sort by nonce (ascending) to maintain ordering
  for account in accountTxs:
    account.txs.sort(by: nonce ascending)

  // Build heap with accounts prioritized by highest effective tip of executable tx
  heap = PriorityHeap()
  for account in accountTxs:
    nextTx = account.txs[0]  // Lowest nonce for account
    if isExecutable(nextTx, account.nonce):  // Nonce matches expected
      tip = EffectiveGasTip(nextTx, baseFee)
      heap.push(account, tip)

  // Extract transactions in tip-descending order
  orderedTxs = []
  while heap.notEmpty():
    account = heap.pop()  // Account with highest tip
    tx = account.txs.shift()  // Remove first (executable) tx
    orderedTxs.append(tx)

    // Re-insert account if more executable txs remain
    if account.txs.notEmpty():
      nextTx = account.txs[0]
      if isExecutable(nextTx, account.nonce + 1):
        tip = EffectiveGasTip(nextTx, baseFee)
        heap.push(account, tip)

  return orderedTxs
