// Constants
COLD_ACCOUNT_ACCESS_COST = 2600
COLD_SLOAD_COST = 2100
WARM_STORAGE_READ_COST = 100

function gasSLoadEIP2929(evm, contract, stack, memory, gasAvailable):
  address = contract.Address()
  slot = stack.peek()

  if evm.StateDB.AddressInAccessList(address):
    if evm.StateDB.SlotInAccessList(address, slot):
      // Warm access: already accessed in this tx
      gas = WARM_STORAGE_READ_COST
    else:
      // Cold access: first access to this slot
      gas = COLD_SLOAD_COST
      evm.StateDB.AddSlotToAccessList(address, slot)
  else:
    // Cold access: first access to this address
    gas = COLD_SLOAD_COST
    evm.StateDB.AddAddressToAccessList(address)
    evm.StateDB.AddSlotToAccessList(address, slot)

  return gas

function gasEip2929AccountCheck(evm, contract, stack, memory, gasAvailable):
  address = stack.peek()

  if not evm.StateDB.AddressInAccessList(address):
    // Cold access: first access to this address
    evm.StateDB.AddAddressToAccessList(address)
    return COLD_ACCOUNT_ACCESS_COST - WARM_STORAGE_READ_COST
  return 0
