function gasSStoreEIP2200(evm, contract, stack, memory, gasAvailable):
  // Fail if not enough gas to cover SSTORE_SENTRY
  if gasAvailable <= params.SstoreSentryGasEIP2200:  // 2300 gas
    return 0, ErrOutOfGas

  slot = stack.peek(0)
  newValue = stack.peek(1)
  currentValue = evm.StateDB.GetState(contract.Address(), slot)
  originalValue = evm.StateDB.GetCommittedState(contract.Address(), slot)

  // Case 1: Storage slot unchanged
  if currentValue == newValue:
    return params.NetSstoreNoopGas  // 200

  // Case 2: Storage slot modified from original value
  if originalValue == currentValue:
    if originalValue == 0:
      return params.NetSstoreInitGas  // 20000 (setting zero to non-zero)
    else:
      if newValue == 0:
        evm.StateDB.AddRefund(params.NetSstoreClearRefund)  // Refund 15000
      return params.NetSstoreCleanGas  // 5000

  // Case 3: Storage slot already modified (dirty)
  gas = params.NetSstoreDirtyGas  // 200

  // Adjust refunds based on transition
  if originalValue != 0:  // Original non-zero
    if currentValue == 0:  // Current zero (about to be set to non-zero)
      evm.StateDB.SubRefund(params.NetSstoreClearRefund)  // Remove refund
    if newValue == 0:  // About to set to zero
      evm.StateDB.AddRefund(params.NetSstoreClearRefund)  // Add refund

  if newValue == originalValue:  // Resetting to original
    if originalValue == 0:
      evm.StateDB.AddRefund(params.NetSstoreResetClearRefund)  // 19800
    else:
      evm.StateDB.AddRefund(params.NetSstoreResetRefund)  // 4800

  return gas
