function VerifyGaslimit(parentGasLimit, currentGasLimit):
  // Constants
  GasLimitBoundDivisor = 1024
  MinGasLimit = 5000
  MaxGasLimit = 0x7fffffffffffffff  // 2^63 - 1

  // Maximum change per block: parent / 1024 (approx 0.0976% per block)
  maxChange = parentGasLimit / GasLimitBoundDivisor
  if maxChange < 1:
    maxChange = 1

  // Check gas limit within bounds
  if currentGasLimit < MinGasLimit:
    return error("gas limit too low")
  if currentGasLimit > MaxGasLimit:
    return error("gas limit too high")

  // Check change not too large
  diff = abs(currentGasLimit - parentGasLimit)
  if diff >= maxChange:
    return error("gas limit changed too quickly")

  return nil
